import assert from 'node:assert/strict';
import {readFile} from 'node:fs/promises';
import {DatabaseSync} from 'node:sqlite';
import {canonical} from '../../server/imports.ts';
import {reviewSourceHashV1 as hash} from '../../scripts/workflow-review-source-facts-v1.mjs';
import {prepareColdCurrentDeploymentContextFileV1 as prepare,recordColdCurrentDeploymentContextFileV1 as record,readColdCurrentDeploymentContextPrivateV1 as privateRead,inspectColdCurrentDeploymentContextFileV1 as inspect,closeColdCurrentDeploymentContextFileV1 as close} from '../../scripts/cold-current-deployment-review-context-files-v2.mjs';
assert.equal(process.argv.length,3);const input=JSON.parse(await readFile(process.argv[2],'utf8')),context=JSON.parse(await readFile(input.fixtureFile,'utf8')).context,db=new DatabaseSync(input.databaseFile,{readOnly:true,allowExtension:false});let owner;
try{owner=await prepare({context,request:input.request,workDirectory:input.workDirectory});assert.equal(inspect(owner).createdContextFile,false);assert.equal(inspect(owner).intentSha256,input.expectedIntentSha256);db.exec('BEGIN');const before=db.prepare('SELECT body,body_hash,phase,details,details_hash FROM cold_control WHERE id=1').get();assert.equal(hash(before.body),before.body_hash);assert.equal(before.body_hash,context.trust.sourceHash);assert.equal(before.phase,'REVIEW_READY_V3');assert.equal(hash(before.details),before.details_hash);const details=JSON.parse(before.details);assert.equal(canonical(details.review),canonical(context.originalReview));const result=await record(owner,{db,details});assert.equal(result.alreadyRecorded,true);assert.equal((await privateRead(owner)).intent.sha256,input.expectedIntentSha256);assert.deepEqual(db.prepare('SELECT body,body_hash,phase,details,details_hash FROM cold_control WHERE id=1').get(),before);db.exec('COMMIT');console.log(JSON.stringify({format:'CURRENT_DEPLOYMENT_CONTEXT_FILE_REOPEN_COMPONENT_V1',intentSha256:input.expectedIntentSha256,reopenedContextFile:true,originalSourceAndReviewUnchanged:true,ownedRuntimeSessionMinted:false,programStartupGranted:false,mqttApplicationProbeGranted:false,businessWritesEnabled:false,formalFieldActivationGranted:false}));}finally{if(db.isTransaction)db.exec('ROLLBACK');db.close();if(owner)await close(owner);}
